/**
 * Endpoint census.
 *
 * `capsule-server/openapi.json` is committed, regenerated by
 * `mise run openapi-kynos`, and drift-gated by `openapi-check-kynos` inside
 * `check-rust`. That makes it the one machine-readable statement of what the
 * server actually serves — and therefore the oracle for every endpoint a design
 * doc names.
 *
 * Matching is **exact on the path template**, deliberately. Normalizing `{id}`
 * to a wildcard would let `POST /v1/albums/{id}/upgrade` pass against the real
 * `/v1/albums/{album_id}/upgrade`, and parameter-name drift (`{opaque-id}` for
 * `{opaque_id}`, `{id}` for `{album_id}`) is a large share of the drift this
 * check exists to find. Missing `/v1` prefixes are most of the rest.
 *
 * Fenced blocks are scanned rather than skipped: a `curl` example naming an
 * endpoint that does not exist is the most harmful kind of wrong.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { walkFiles } from './lib/walk.mjs';

/** The committed contract this check resolves against. */
const CONTRACT = 'capsule-server/openapi.json';

/** Docs scanned. */
const DOCS_ROOT = 'capsule-docs/src/content/docs';

/**
 * Deliberately-unimplemented surfaces, as `<file>\t<METHOD /path>\t<reason>`.
 * Keyed on the citation rather than a line number, so reflowing a paragraph
 * does not churn the file. Mirrors `locales/i18n-guard-allowlist.txt`.
 */
const ALLOWLIST = 'capsule-docs/endpoint-census-allowlist.txt';

const METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS'];

/**
 * Path prefixes that make a bare backticked token an endpoint citation.
 *
 * `/u/` is deliberately absent: it is `capsule-web`'s page namespace — the page
 * a guest opens — and never an API namespace, so a `/u/…` citation is correct
 * prose about the browser rather than a claim about the contract.
 */
const PATH_PREFIXES = ['/v1/', '/s/', '/d/', '/.well-known/'];

/** Strip a query string, a trailing ellipsis, and surrounding punctuation. */
function normalizePath(raw) {
    return raw
        .split('?')[0]
        .replace(/[.,;:]+$/, '')
        .replace(/\/+$/, (match, offset) => (offset === 0 ? match : ''));
}

/** Read the operations the committed contract declares, as `METHOD /path`. */
function contractOperations(root) {
    const file = join(root, CONTRACT);
    if (!existsSync(file)) return null;
    const document = JSON.parse(readFileSync(file, 'utf8'));
    const operations = new Set();
    for (const [path, item] of Object.entries(document.paths ?? {})) {
        for (const method of Object.keys(item)) {
            if (METHODS.includes(method.toUpperCase())) {
                operations.add(`${method.toUpperCase()} ${path}`);
            }
        }
    }
    return operations;
}

/** Load the allowlist as a set of `file\tMETHOD /path` keys, plus its raw rows. */
function loadAllowlist(root) {
    const file = join(root, ALLOWLIST);
    const keys = new Set();
    if (!existsSync(file)) return keys;
    for (const line of readFileSync(file, 'utf8').split('\n')) {
        const row = line.trim();
        if (!row || row.startsWith('#')) continue;
        const [source, citation] = row.split('\t');
        if (source && citation)
            keys.add(`${source.trim()}\t${citation.trim()}`);
    }
    return keys;
}

/**
 * Every endpoint citation in a document: `METHOD /path`, the compound
 * `POST/HEAD/PATCH /upload` form the docs use, and bare backticked paths.
 *
 * @returns {{ citation: string, line: number }[]}
 */
export function endpointCitations(source) {
    const found = [];
    const methods = METHODS.join('|');
    const at = (index) => source.slice(0, index).split('\n').length;

    const methodful = new RegExp(
        `\`((?:${methods})(?:/(?:${methods}))*)\\s+(/[^\`]*)\``,
        'g',
    );
    for (const match of source.matchAll(methodful)) {
        const path = normalizePath(match[2].trim());
        for (const method of match[1].split('/')) {
            found.push({
                citation: `${method} ${path}`,
                line: at(match.index),
            });
        }
    }

    for (const match of source.matchAll(/`(\/[^`\s]*)`/g)) {
        const path = normalizePath(match[1]);
        if (!PATH_PREFIXES.some((prefix) => path.startsWith(prefix))) continue;
        found.push({ citation: path, line: at(match.index) });
    }

    return found;
}

/** Loosen a path enough to suggest what the author probably meant. */
function shape(path) {
    return path
        .replace(/^\/v1/, '')
        .replace(/\{[^}]*\}/g, '{}')
        .toLowerCase();
}

/**
 * @param {string} root Absolute repo root.
 * @returns {{ findings: string[], checked: number }}
 */
export function checkEndpointCensus(root) {
    const operations = contractOperations(root);
    if (operations === null) {
        return {
            findings: [
                `${CONTRACT} is missing; regenerate it with \`mise run openapi-kynos\`.`,
            ],
            checked: 0,
        };
    }

    const allowed = loadAllowlist(root);
    const paths = new Set(
        [...operations].map((op) => op.slice(op.indexOf(' ') + 1)),
    );
    const byShape = new Map();
    for (const path of paths) {
        if (!byShape.has(shape(path))) byShape.set(shape(path), path);
    }

    const findings = [];
    const exercised = new Set();
    let checked = 0;

    for (const source of walkFiles(root, (rel) =>
        rel.startsWith(`${DOCS_ROOT}/`),
    )) {
        const body = readFileSync(join(root, source), 'utf8');
        for (const { citation, line } of endpointCitations(body)) {
            checked += 1;
            const key = `${source}\t${citation}`;
            if (allowed.has(key)) {
                exercised.add(key);
                continue;
            }

            const hasMethod = citation.includes(' ');
            const path = hasMethod
                ? citation.slice(citation.indexOf(' ') + 1)
                : citation;
            if (hasMethod ? operations.has(citation) : paths.has(path))
                continue;

            const suggestion = byShape.get(shape(path));
            const hint =
                suggestion && suggestion !== path
                    ? `did you mean ${suggestion}?`
                    : hasMethod && paths.has(path)
                      ? 'that path exists but not with this method'
                      : 'no operation with this path';
            findings.push(`${source}:${line}  ${citation}  (${hint})`);
        }
    }

    // An exemption that no longer matches a citation is an exemption nobody
    // will notice has stopped being true. Same rule `i18n_guard` applies to its
    // own allowlist.
    for (const key of allowed) {
        if (!exercised.has(key)) {
            const [source, citation] = key.split('\t');
            findings.push(
                `${ALLOWLIST}  ${source} no longer cites ${citation}; remove the stale exemption`,
            );
        }
    }

    return { findings, checked };
}

/** @param {{ findings: string[], checked: number }} result */
export function reportEndpointCensus({ findings, checked }) {
    if (findings.length === 0) {
        return `endpoint-census: ${checked} citation(s) checked, all resolve.`;
    }
    return [
        `endpoint-census: ${findings.length} citation(s) do not resolve to ${CONTRACT}.`,
        'Regenerate the contract with `mise run openapi-kynos` if the server changed;',
        `otherwise fix the doc, or add a "<file>\\t<METHOD /path>\\t<reason>" line to ${ALLOWLIST}.`,
        '',
        ...findings.map((f) => `  ${f}`),
        '',
        `endpoint-census failed: ${findings.length} unresolved of ${checked} checked.`,
    ].join('\n');
}

export const endpointCensusCheck = {
    name: 'endpoint-census',
    run: checkEndpointCensus,
    report: reportEndpointCensus,
};
